import { Group, Mesh, PlaneGeometry, Color, DirectionalLight, AmbientLight, EquirectangularReflectionMapping, SphereGeometry, MeshStandardNodeMaterial, Vector3, Matrix4 } from 'three/webgpu';
import { uniform, time, mix, smoothstep, uv, vec3, float, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'collection-stat-tile';

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const accentColor = new THREE.Color(palette.accent);
  const inkColor = new THREE.Color(palette.ink);
  const surfaceColor = new THREE.Color(palette.surface);
  const paperColor = new THREE.Color(palette.paper);

  const resourceCleanups = [];
  const tweens = [];

  // --- Backdrop plane with vertical gradient ---
  const backdropGeo = new THREE.PlaneGeometry(8, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.85,
    metalness: 0.15,
  });

  const gradTop = uniform(vec3(inkColor.r, inkColor.g, inkColor.b));
  const gradBot = uniform(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b));
  backdropMat.colorNode = mix(gradBot, gradTop, uv().y);
  backdropMat.emissiveNode = mix(vec3(0.005, 0.005, 0.008), vec3(0.012, 0.012, 0.018), uv().y);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.6);
  group.add(backdrop);

  // --- Contact shadow plane ---
  const shadowGeo = new THREE.PlaneGeometry(2.0, 1.2);
  const shadowMat = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 0.0,
    roughness: 1.0,
    metalness: 0.0,
  });
  const shadowCenter = uniform(float(0.55));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(float(0.0), float(1.0), uniform(float(1.0)).sub(uv().sub(vec2(0.5, 0.5)).length())).mul(shadowCenter);
  shadowMat.depthWrite = false;
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -0.32;
  shadowPlane.position.z = 0.0;
  group.add(shadowPlane);

  // --- Lights ---
  const ambient = new THREE.AmbientLight(0xffffff, 0.45);
  group.add(ambient);

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
  keyLight.position.set(1.8, 1.5, 2.0);
  keyLight.angle = Math.PI / 4;
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(accentColor.getHex(), 0.75);
  rimLight.position.set(-1.6, 0.4, -1.5);
  group.add(rimLight);

  const fillLight = new THREE.DirectionalLight(0x90949a, 0.35);
  fillLight.position.set(0.8, -0.6, 1.4);
  group.add(fillLight);

  // --- Surface plate (machined base for the tile) ---
  const baseGeo = new THREE.BoxGeometry(1.4, 0.05, 1.0);
  const baseMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(palette.ink),
    roughness: 0.55,
    metalness: 0.45,
  });
  const basePlate = new THREE.Mesh(baseGeo, baseMat);
  basePlate.position.set(0, -0.28, 0);
  group.add(basePlate);

  // --- Accent brush trim on front edge ---
  const trimGeo = new THREE.BoxGeometry(1.3, 0.015, 0.03);
  const trimMat = new MeshStandardNodeMaterial({
    color: accentColor,
    roughness: 0.4,
    metalness: 0.6,
    emissive: accentColor,
    emissiveIntensity: 0.8,
  });
  const trim = new THREE.Mesh(trimGeo, trimMat);
  trim.position.set(0, -0.255, 0.5);
  group.add(trim);

  // --- Load GLB gear mesh ---
  const glbUrl = config.meshUrl ?? config.intent?.visualSpec?.meshUrl ?? '/prism-mock/orrery/meshes/gear-a.glb';
  let glbRoot = null;

  if (glbUrl && ctx.glbLoader) {
    ctx.glbLoader.loadGLB(glbUrl).then((gltf) => {
      glbRoot = gltf.scene;

      // Scale and position the gear as the stat tile's machined surface element
      glbRoot.traverse((child) => {
        if (child.isMesh) {
          if (child.material) {
            // Enhance PBR for machined metal look
            if (child.material.roughness !== undefined) {
              child.material.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
            }
            if (child.material.metalness !== undefined) {
              child.material.metalness = Math.min(child.material.metalness ?? 0.4, 0.55);
            }
            if (child.material.clearcoat !== undefined) {
              child.material.clearcoat = Math.min(child.material.clearcoat ?? 0.1, 0.25);
            }
            child.castShadow = true;
            child.receiveShadow = true;
          }
        }
      });

      // Compact stat tile sizing
      glbRoot.scale.setScalar(0.35);
      glbRoot.position.set(0, 0.02, 0);
      glbRoot.rotation.set(0, 0, 0);

      group.add(glbRoot);
    }).catch(() => {
      // Fallback: build a compact card mesh if GLB fails
      const cardGeo = new THREE.BoxGeometry(1.2, 0.02, 0.8);
      const cardMat = new MeshStandardNodeMaterial({
        color: inkColor,
        roughness: 0.55,
        metalness: 0.5,
      });
      const card = new THREE.Mesh(cardGeo, cardMat);
      card.position.set(0, -0.22, 0);
      group.add(card);
    });
  }

  // --- Accent emissive core dot (the "metric" indicator) ---
  const dotGeo = new THREE.SphereGeometry(0.035, 24, 24);
  const dotMat = new MeshStandardNodeMaterial({
    color: accentColor,
    emissive: accentColor,
    emissiveIntensity: 1.8,
    roughness: 0.3,
    metalness: 0.4,
  });
  const dot = new THREE.Mesh(dotGeo, dotMat);
  dot.position.set(-0.5, 0.08, 0.42);
  group.add(dot);

  // The dot is the brightest element — ensure nothing else exceeds it
  // Cap other emissives

  // --- Entrance animation (weighted-settle) ---
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y = (config.scenePosition?.[1] ?? 0) + 0.4;

  const enterTimeline = gsap.timeline();
  tweens.push(enterTimeline);
  enterTimeline.to(group.position, {
    y: config.scenePosition?.[1] ?? -0.2,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  enterTimeline.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.65,
    ease: 'power3.out',
  }, 0.05);
  enterTimeline.to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.6);

  // Fade in
  group.traverse((child) => {
    if (child.isMesh && child.material) {
      const mat = child.material;
      if (mat.opacity !== undefined && mat.transparent !== undefined) {
        // skip
      }
    }
  });

  const opacityProxy = { v: 0 };
  tweens.push(gsap.to(opacityProxy, {
    v: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      group.traverse((child) => {
        if (child.isMesh && child.material) {
          if (child !== backdrop && child !== shadowPlane && child !== basePlate) {
            child.visible = opacityProxy.v > 0.01;
          }
        }
      });
    },
  }));

  // --- Apply cinematic primitives ---
  const primitiveResults = [];
  const primitives = config.cinematicPrimitives ?? [];

  for (const prim of primitives) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      try {
        const result = ctx.primitives[prim.name](group, prim.params ?? {});
        if (result) primitiveResults.push(result);
      } catch (e) {
        // primitive application failed - continue
      }
    }
  }

  // --- Interactions ---
  const originalY = config.scenePosition?.[1] ?? -0.2;
  const hoverProxy = { offset: 0, rotX: 0, rotZ: 0 };
  let hoverActive = false;

  const hoverTimeline = gsap.timeline({ paused: true });
  tweens.push(hoverTimeline);
  hoverTimeline.to(hoverProxy, {
    offset: 0.15,
    duration: 0.4,
    ease: 'power2.out',
    onUpdate: () => {
      group.position.y = originalY + hoverProxy.offset;
    },
  }, 0);
  hoverTimeline.to(group.rotation, {
    x: 0.04,
    z: -0.02,
    duration: 0.35,
    ease: 'power2.out',
  }, 0);
  hoverTimeline.to(dotMat, {
    emissiveIntensity: 2.3,
    duration: 0.4,
    ease: 'power2.out',
  }, 0);

  group.userData.handlers = {
    hover: () => {
      hoverActive = true;
      hoverTimeline.play();
    },
    unhover: () => {
      hoverActive = false;
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-collection.select', { source: 'collection-stat-tile' });
      // press-down feedback
      const pressTl = gsap.timeline();
      tweens.push(pressTl);
      pressTl.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'power2.in',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1.0, y: 1.0, z: 1.0,
            duration: 0.25,
            ease: 'power4.out',
          });
        },
      });
    },
  };

  // --- Cleanup ---
  const allGeometries = [backdropGeo, shadowGeo, baseGeo, trimGeo, dotGeo];
  const allMaterials = [backdropMat, shadowMat, baseMat, trimMat, dotMat];

  group.userData.cleanup = () => {
    tweens.forEach((t) => {
      if (t && t.kill) t.kill();
    });
    primitiveResults.forEach((r) => {
      if (r && r.cleanup) {
        try { r.cleanup(); } catch (e) { /* noop */ }
      }
    });
    allGeometries.forEach((g) => {
      if (g && g.dispose) g.dispose();
    });
    allMaterials.forEach((m) => {
      if (m && m.dispose) m.dispose();
    });
    if (glbRoot) {
      glbRoot.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material && child.material.dispose) child.material.dispose();
        }
      });
    }
  };

  return group;
}
